import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    s1 = input_data[1]
    s2 = input_data[2]

    m = n - 1

    def get_next_move(s, idx):
        if idx < m:
            return s[idx]
        return None

    def get_prev_move(s, idx):
        if idx > 0:
            return s[idx - 1]
        return None

    def opposite(move):
        if move == 'N':
            return 'S'
        elif move == 'S':
            return 'N'
        elif move == 'E':
            return 'W'
        elif move == 'W':
            return 'E'
        return None

    def can_move(s, idx, direction):
        next_move = get_next_move(s, idx)
        prev_move = get_prev_move(s, idx)

        if direction == 'N':
            if next_move == 'N':
                return True
            if prev_move == 'S':
                return True
        elif direction == 'S':
            if next_move == 'S':
                return True
            if prev_move == 'N':
                return True
        elif direction == 'E':
            if next_move == 'E':
                return True
            if prev_move == 'W':
                return True
        elif direction == 'W':
            if next_move == 'W':
                return True
            if prev_move == 'E':
                return True
        return False

    dp = {}

    start_state = (0, 0)
    target_state = (m, m)

    queue = [start_state]
    visited = set([start_state])

    while queue:
        curr = queue.pop(0)
        i, j = curr

        if i == m and j == m:
            print("YES")
            return

        moves = ['N', 'S', 'E', 'W']

        for move in moves:
            if not can_move(s1, i, move) and not can_move(s2, j, move):
                continue

            new_i = i
            new_j = j

            if can_move(s1, i, move):
                if move == get_next_move(s1, i):
                    new_i = i + 1
                else:
                    new_i = i - 1

            if can_move(s2, j, move):
                if move == get_next_move(s2, j):
                    new_j = j + 1
                else:
                    new_j = j - 1

            if (new_i, new_j) not in visited:
                visited.add((new_i, new_j))
                queue.append((new_i, new_j))

    print("NO")

if __name__ == "__main__":
